style.css:
@-moz-document domain("youtube.com") {
/* Body background color */
    body {
        background-color: #f9e09e !important;
        color: #9e8c5d !important;
    }

    /* Header background color */
    #masthead {
        background-color: #f9e09e !important;
    }

    /* Change colors of buttons */
    #buttons ytd-toggle-button-renderer {
        background-color: #ffcc66 !important;
    }

    /* Apply font style */
    * {
        font-family: "Comic Sans MS", sans-serif !important;
    }

    /* Style the video thumbnails */
    ytd-rich-item-renderer {
        border: 3px solid #f5d66d !important;
    }

    /* Modify the sidebar background */
    #secondary {
        background-color: #f7e1b2 !important;
    }

    /* Title text styling */
    ytd-video-renderer h3 {
        color: #9e8c5d !important;
    }
}
